"use client";

import { Sequencer as SequencerPrimitive } from "@audio-ui/react";
import { cn } from "@/lib/utils";

type SequencerProps = Omit<SequencerPrimitive.Root.Props, "className"> & {
  className?: string;
  /** Names each row, such as "Kick": it labels the row for assistive technology and is written beside it. */
  rowLabels?: readonly string[];
  /** Highlights every `beatEvery` steps, such as 4 for a beat in sixteenths. */
  beatEvery?: number;
  /** Draws a bar under each row to set how loud every step plays: press or drag across it; Alt + click returns a step to full. */
  showVelocity?: boolean;
};

/**
 * A step sequencer: a row of steps per sound. Press a step to flip it and
 * drag on to paint the same state across the others; the arrow keys move
 * between steps and Space flips one. Pass `source` with the step being played
 * and its column lights up. With `showVelocity`, a bar under each row sets
 * how loud each step plays; pass `velocities` and `onVelocityChange` to follow
 * them.
 */
function Sequencer({
  beatEvery = 4,
  className,
  rowLabels,
  showVelocity = false,
  ...props
}: SequencerProps) {
  return (
    <SequencerPrimitive.Root
      className={cn(
        "[--sequencer-off:var(--muted)] flex w-full min-w-0 select-none flex-col gap-1.5 data-disabled:opacity-50",
        className
      )}
      data-slot="sequencer"
      {...props}
    >
      <SequencerPrimitive.Rows>
        {(row) => (
          <SequencerPrimitive.Row
            aria-label={rowLabels?.[row] ?? `Row ${row + 1}`}
            className="flex items-center gap-2"
            index={row}
          >
            {rowLabels ? (
              <span
                aria-hidden="true"
                className="w-12 shrink-0 text-muted-foreground text-xs"
              >
                {rowLabels[row]}
              </span>
            ) : null}
            <div className="flex min-w-0 flex-1 flex-col gap-1">
              <div className="grid grid-flow-col auto-cols-fr gap-1">
                <SequencerPrimitive.Cells>
                  {(step) => (
                    <SequencerPrimitive.Cell
                      aria-label={`${rowLabels?.[row] ?? `Row ${row + 1}`}, step ${step + 1}`}
                      className={cn(
                        "rounded-[min(var(--radius-sm),6px)] border bg-muted/60 transition-[background-color,box-shadow,transform] duration-100 ease-out hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring/50 active:scale-95 aria-pressed:border-primary aria-pressed:bg-primary data-current:ring-2 data-current:ring-foreground/40 data-disabled:pointer-events-none motion-reduce:transition-none motion-reduce:active:scale-100 h-9 min-w-0 cursor-pointer touch-none outline-none",
                        step % beatEvery === 0 && "bg-muted"
                      )}
                      step={step}
                    />
                  )}
                </SequencerPrimitive.Cells>
              </div>
              {showVelocity ? (
                <div className="grid grid-flow-col auto-cols-fr gap-1">
                  <SequencerPrimitive.Cells>
                    {(step) => (
                      <SequencerPrimitive.Velocity
                        aria-label={`${rowLabels?.[row] ?? `Row ${row + 1}`}, step ${step + 1} velocity`}
                        className="overflow-hidden rounded-[min(var(--radius-sm),6px)] bg-muted/40 focus-within:ring-2 focus-within:ring-ring/50 data-disabled:pointer-events-none relative h-8 min-w-0 cursor-ns-resize touch-none outline-none"
                        step={step}
                      >
                        <span className="bg-primary absolute inset-x-0 bottom-0 h-[calc(var(--sequencer-velocity)*100%)]" />
                      </SequencerPrimitive.Velocity>
                    )}
                  </SequencerPrimitive.Cells>
                </div>
              ) : null}
            </div>
          </SequencerPrimitive.Row>
        )}
      </SequencerPrimitive.Rows>
    </SequencerPrimitive.Root>
  );
}

export { Sequencer };

"use client";

import { createSource } from "@audio-ui/react";
import { useCallback, useEffect, useRef, useState } from "react";
import { IconPlaceholder } from "@/app/(create)/components/icon-placeholder";
import { Button } from "@/components/ui/button";
import { Sequencer } from "@/components/audio/elements/sequencer";
import { useMasterBus } from "@/hooks/use-master-bus";
import { useTransportClock } from "@/hooks/use-transport-clock";
import { useWebAudio } from "@/hooks/use-web-audio";
import {
  triggerHihat,
  triggerKick,
  triggerSnare,
} from "@/lib/drum-synthesis";

const STEPS = 16;
const STEPS_PER_BEAT = 4;
const BPM = 112;
const VOLUME = 0.7;
const ROWS = ["Kick", "Snare", "Hihat"];
const TRIGGERS = [triggerKick, triggerSnare, triggerHihat];

const VELOCITIES = [
  [1, 0.5, 0.7, 0.5, 0.9, 0.5, 0.7, 0.5, 1, 0.5, 0.7, 0.5, 0.9, 0.5, 0.7, 0.6],
  [1, 1, 1, 1, 0.8, 1, 1, 1, 1, 1, 1, 1, 0.85, 1, 1, 0.4],
  [0.55, 0.6, 0.9, 0.6, 0.55, 0.6, 0.9, 0.6, 0.55, 0.6, 0.9, 0.6, 0.55, 0.6, 0.9, 0.6],
];

const x = (steps: number[]) =>
  Array.from({ length: STEPS }, (_, step) => steps.includes(step));
const BEAT = [x([0, 4, 8, 12]), x([4, 12]), x([2, 6, 10, 14])];

/** A drum machine: draw a pattern and hear it. Press a step, or drag across several; the playing column lights up. */
export function SequencerDemo() {
  const [pattern, setPattern] = useState(BEAT);
  const patternRef = useRef(pattern);
  patternRef.current = pattern;
  const [velocities, setVelocities] = useState(VELOCITIES);
  const velocitiesRef = useRef(velocities);
  velocitiesRef.current = velocities;
  const [step] = useState(() => createSource(-1));
  const webAudio = useWebAudio();
  const master = useMasterBus(VOLUME);

  const playStep = useCallback(
    (index: number, time: number) => {
      const ctx = webAudio.getContext();
      if (!(ctx && master)) {
        return;
      }
      patternRef.current.forEach((row, at) => {
        if (!row[index]) {
          return;
        }
        // Each hit goes through a gain of its own: the step's velocity.
        const hit = ctx.createGain();
        hit.gain.value = velocitiesRef.current[at]?.[index] ?? 1;
        hit.connect(master);
        TRIGGERS[at]?.(ctx, hit, time);
      });
    },
    [master, webAudio]
  );
  const { getPosition, isPlaying, start, stop } = useTransportClock({
    bpm: BPM,
    onStep: playStep,
    stepsPerBeat: STEPS_PER_BEAT,
    totalSteps: STEPS,
  });

  useEffect(() => {
    if (!isPlaying) {
      step.set(-1);
      return;
    }
    let frame = 0;
    const tick = () => {
      step.set(Math.floor(getPosition()) % STEPS);
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [getPosition, isPlaying, step]);

  const toggle = useCallback(
    () => (isPlaying ? stop() : start()),
    [isPlaying, start, stop]
  );
  const clear = useCallback(
    () =>
      setPattern(ROWS.map(() => Array.from({ length: STEPS }, () => false))),
    []
  );

  return (
    <div className="flex w-full max-w-xl flex-col gap-3">
      <Sequencer
        aria-label="Drum pattern"
        onValueChange={setPattern}
        onVelocityChange={setVelocities}
        rowLabels={ROWS}
        showVelocity
        source={step}
        value={pattern}
        velocities={velocities}
      />
      <div className="flex items-center justify-between gap-2">
        <Button
          aria-label={isPlaying ? "Stop" : "Play"}
          onClick={toggle}
          size="icon-sm"
          variant="outline"
        >
          <IconPlaceholder
            hugeicons={isPlaying ? "PauseIcon" : "PlayIcon"}
            lucide={isPlaying ? "PauseIcon" : "PlayIcon"}
            phosphor={isPlaying ? "PauseIcon" : "PlayIcon"}
            remixicon={isPlaying ? "RiPauseLine" : "RiPlayLine"}
            tabler={isPlaying ? "IconPlayerPause" : "IconPlayerPlay"}
          />
        </Button>
        <Button onClick={clear} size="sm" variant="ghost">
          Clear
        </Button>
      </div>
    </div>
  );
}
